// @FIGURE_CODE_BEGIN
var theta1 = 30, ratio = 0.66;
var RAYCOL = '#1f7fae';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
setPlotFrame({ xDomain: [-4, 4], yDomain: [-3, 3], margin: 26, draw: draw });

function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function screenAngle(dx, dy) { // world direction -> screen angle (y down)
  var f = _plotFrame;
  return Math.atan2(-dy * f.sy, dx * f.sx);
}
function arcPts(cx, cy, r, a0, a1) {
  var n = 26, s = [];
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * (i / n);
    s.push((cx + r * Math.cos(a)) + ',' + (cy + r * Math.sin(a)));
  }
  return s.join(' ');
}
function txt(x, y, str, size, color, anchor, italic) {
  var t = draw.text(str).move(x, y).font({ size: size, family: 'Georgia, serif', anchor: anchor || 'start' })
    .fill(color || '#111').attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  if (italic) t.font({ style: 'italic' });
  return t;
}
function arrowHead(x, y, ang, size, color) {
  var a1 = ang + Math.PI - 0.42, a2 = ang + Math.PI + 0.42;
  draw.polygon([
    x + ',' + y,
    (x + size * Math.cos(a1)) + ',' + (y + size * Math.sin(a1)),
    (x + size * Math.cos(a2)) + ',' + (y + size * Math.sin(a2))
  ]).fill(color);
}
function ray(x0, y0, x1, y1, color, width, dashed, opacity) {
  var l = draw.line(x0, y0, x1, y1).stroke({ color: color, width: width, linecap: 'round' });
  if (dashed) l.attr('stroke-dasharray', '6,5');
  if (opacity != null) l.opacity(opacity);
  return l;
}

function build() {
  draw.clear();
  var f = _plotFrame;
  var cx = plotX(0), cy = plotY(0);
  var xL = plotX(-4), xR = plotX(4), yTop = plotY(0), yBot = plotY(-3);
  var L = 2.45;
  var minDim = Math.min(f.width, f.height);
  var arcR = Math.max(28, 0.16 * minDim);
  var ah = Math.max(7, 0.022 * minDim);

  // lower medium shading
  draw.rect(xR - xL, yBot - yTop).move(xL, yTop).fill('#cfe2ef');
  // interface
  ray(xL, yTop, xR, yTop, '#5b8aa6', 2, false, 1);
  // normal (dashed vertical)
  ray(cx, plotY(2.75), cx, plotY(-2.75), '#444', 1.2, true, 1);

  // medium labels
  txt(plotX(-3.55), plotY(2.35), 'n₂', 18, '#111', 'start', true);
  txt(plotX(3.35), plotY(-0.75), 'n₁', 18, '#111', 'start', true);

  var t1 = rad(theta1);
  var thetaC = deg(Math.asin(Math.min(1, ratio)));
  var tC = rad(thetaC);
  var sinT2 = Math.sin(t1) / ratio;
  var transmitting = sinT2 <= 1;
  var theta2 = transmitting ? deg(Math.asin(sinT2)) : 90;
  var t2 = rad(theta2);

  var downAng = Math.PI / 2;            // screen angle of downward normal
  var upAng = -Math.PI / 2;             // upward normal

  // ---- critical reference ray (dashed, incident side) ----
  var cEndX = plotX(-L * Math.sin(tC)), cEndY = plotY(-L * Math.cos(tC));
  ray(cx, cy, cEndX, cEndY, '#7a7a7a', 1.4, true, 0.9);
  // theta_c arc (between down-normal and critical ray)
  var cAng = screenAngle(-Math.sin(tC), -Math.cos(tC));
  draw.polyline(arcPts(cx, cy, arcR * 1.18, downAng, cAng)).fill('none').stroke({ color: '#555', width: 1 });
  var cMid = (downAng + cAng) / 2;
  txt(cx + (arcR * 1.18 + 12) * Math.cos(cMid), cy + (arcR * 1.18 + 12) * Math.sin(cMid) - 4, 'θ_c', 14, '#333', 'middle', true);

  // ---- incident ray ----
  var iTailX = plotX(-L * Math.sin(t1)), iTailY = plotY(-L * Math.cos(t1));
  ray(iTailX, iTailY, cx, cy, RAYCOL, 2.4, false, 1);
  var iAng = screenAngle(Math.sin(t1), Math.cos(t1)); // toward origin
  var iMidX = iTailX + (cx - iTailX) * 0.5, iMidY = iTailY + (cy - iTailY) * 0.5;
  arrowHead(iMidX, iMidY, iAng, ah, RAYCOL);
  // theta_1 incident arc (down-normal to incident tail dir)
  var iTailAng = screenAngle(-Math.sin(t1), -Math.cos(t1));
  draw.polyline(arcPts(cx, cy, arcR, downAng, iTailAng)).fill('none').stroke({ color: '#333', width: 1 });
  var iMidA = (downAng + iTailAng) / 2;
  txt(cx + (arcR + 12) * Math.cos(iMidA), cy + (arcR + 12) * Math.sin(iMidA) - 4, 'θ₁', 14, '#111', 'middle', true);
  txt(iTailX - 6, iTailY - 10, 'Incident ray', 13, '#111', 'end', false);

  // ---- reflected ray (always) ----
  var rEndX = plotX(L * Math.sin(t1)), rEndY = plotY(-L * Math.cos(t1));
  ray(cx, cy, rEndX, rEndY, RAYCOL, 2.4, false, 1);
  var rAng = screenAngle(Math.sin(t1), -Math.cos(t1));
  arrowHead(rEndX, rEndY, rAng, ah, RAYCOL);
  var rTailAng = screenAngle(Math.sin(t1), -Math.cos(t1));
  draw.polyline(arcPts(cx, cy, arcR, rTailAng, downAng)).fill('none').stroke({ color: '#333', width: 1 });
  var rMidA = (rTailAng + downAng) / 2;
  txt(cx + (arcR + 12) * Math.cos(rMidA), cy + (arcR + 12) * Math.sin(rMidA) - 4, 'θ₁', 14, '#111', 'middle', true);
  txt(rEndX + 4, rEndY + 6, 'Reflected ray', 13, '#111', 'start', false);

  // ---- refracted ray / tangent / TIR ----
  var atCrit = Math.abs(theta1 - thetaC) <= 1.0;
  var tir = theta1 > thetaC + 1.0;
  var refrOp = transmitting ? Math.max(0, Math.min(1, (thetaC - theta1) / 2)) : 0;

  if (refrOp > 0.02) {
    var fEndX = plotX(L * Math.sin(t2)), fEndY = plotY(L * Math.cos(t2));
    ray(cx, cy, fEndX, fEndY, RAYCOL, 2.4, false, refrOp);
    var fAng = screenAngle(Math.sin(t2), Math.cos(t2));
    arrowHead(fEndX, fEndY, fAng, ah, RAYCOL).opacity(refrOp);
    var fAngArc = screenAngle(Math.sin(t2), Math.cos(t2));
    draw.polyline(arcPts(cx, cy, arcR, upAng, fAngArc)).fill('none').stroke({ color: '#333', width: 1 }).opacity(refrOp);
    var fMidA = (upAng + fAngArc) / 2;
    txt(cx + (arcR + 12) * Math.cos(fMidA), cy + (arcR + 12) * Math.sin(fMidA) - 4, 'θ₂', 14, '#111', 'middle', true).opacity(refrOp);
    txt(fEndX + 4, fEndY - 8, 'Refracted ray', 13, '#111', 'start', false).opacity(refrOp);
  }

  if (atCrit) {
    // tangent refracted ray along interface to the right
    ray(cx, cy, plotX(L), cy, RAYCOL, 2.4, false, 1);
    arrowHead(plotX(L), cy, 0, ah, RAYCOL);
    // right-angle square marker (upper-right quadrant)
    var s = Math.max(9, 0.03 * minDim);
    draw.polyline([cx + ',' + (cy - s), (cx + s) + ',' + (cy - s), (cx + s) + ',' + cy])
      .fill('none').stroke({ color: '#222', width: 1.4 });
    txt(cx + s + 6, cy - s - 4, 'θ₂ = 90°', 14, '#111', 'start', true);
  }

  if (tir) {
    txt(plotX(1.5), plotY(-1.4), 'Total', 14, '#111', 'start', false);
    txt(plotX(1.5), plotY(-1.4) + 16, 'internal', 14, '#111', 'start', false);
    txt(plotX(1.5), plotY(-1.4) + 32, 'reflection', 14, '#111', 'start', false);
  }

  // hover tooltip on incidence point region
