<p id="demoNarration" style="margin:0;font-size:10px;max-width:210px;line-height:1.35"></p>
<div style="display:flex;align-items:center;gap:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:10px"></span>
  <button onclick="nextStep()">▶</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var theta1 = 30, ratio = 0.66;
var RAYCOL = '#1c7fae';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
setPlotFrame({ xDomain: [-4, 4], yDomain: [-3, 3], margin: 26, draw: draw });

function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function screenAngle(dx, dy) {
  var f = _plotFrame;
  return Math.atan2(-dy * f.sy, dx * f.sx);
}
function arcPts(cx, cy, r, a0, a1) {
  var n = 28, s = [];
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * (i / n);
    s.push((cx + r * Math.cos(a)).toFixed(2) + ',' + (cy + r * Math.sin(a)).toFixed(2));
  }
  return s.join(' ');
}
function txt(x, y, str, size, color, anchor, italic) {
  var t = draw.text(str).move(x, y)
    .font({ size: size, family: 'Georgia, "Times New Roman", serif', anchor: anchor || 'start' })
    .fill(color || '#111')
    .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  if (italic) t.font({ style: 'italic' });
  return t;
}
function arrowHead(x, y, ang, size, color) {
  var a1 = ang + Math.PI - 0.42, a2 = ang + Math.PI + 0.42;
  return draw.polygon([
    x + ',' + y,
    (x + size * Math.cos(a1)).toFixed(2) + ',' + (y + size * Math.sin(a1)).toFixed(2),
    (x + size * Math.cos(a2)).toFixed(2) + ',' + (y + size * Math.sin(a2)).toFixed(2)
  ]).fill(color);
}
function ray(x0, y0, x1, y1, color, width, dashed, opacity) {
  var l = draw.line(x0, y0, x1, y1).stroke({ color: color, width: width, linecap: 'round' });
  if (dashed) l.attr('stroke-dasharray', '6,5');
  if (opacity != null) l.opacity(opacity);
  return l;
}

function build() {
  draw.clear();
  var f = _plotFrame;
  var cx = plotX(0), cy = plotY(0);
  var xL = plotX(-4), xR = plotX(4), yTop = plotY(0), yBot = plotY(-3);
  var L = 2.5;
  var minDim = Math.min(f.width, f.height);
  var arcR = Math.max(26, 0.15 * minDim);
  var ah = Math.max(7, 0.024 * minDim);

  // lower medium (n1) shading
  draw.rect(xR - xL, yBot - yTop).move(xL, yTop)
    .fill('#cfe2ef').stroke({ color: '#9fc0d6', width: 1 });
  // interface line
  ray(xL, yTop, xR, yTop, '#5b8aa6', 2, false, 1);
  // normal (dashed vertical)
  ray(cx, plotY(2.8), cx, plotY(-2.8), '#444', 1.2, true, 1);

  // medium labels
  txt(plotX(-3.6), plotY(2.35), 'n₂', 19, '#111', 'start', true);
  txt(plotX(3.25), plotY(-0.7), 'n₁', 19, '#111', 'start', true);

  var t1 = rad(theta1);
  var thetaC = deg(Math.asin(Math.min(1, ratio)));
  var tC = rad(thetaC);
  var sinT2 = Math.sin(t1) / ratio;
  var transmitting = sinT2 <= 1;
  var theta2 = transmitting ? deg(Math.asin(sinT2)) : 90;
  var t2 = rad(theta2);

  var downAng = Math.PI / 2;
  var upAng = -Math.PI / 2;

  var atCrit = Math.abs(theta1 - thetaC) <= 1.0;
  var tir = theta1 > thetaC + 1.0;
  var refr = !atCrit && !tir;
  var showCritRef = theta1 >= thetaC - 6;

  // ---- dashed critical-angle reference ray (inside n1, left of normal) ----
  if (showCritRef) {
    var cEndX = plotX(-L * Math.sin(tC)), cEndY = plotY(-L * Math.cos(tC));
    ray(cx, cy, cEndX, cEndY, '#6f6f6f', 1.4, true, 0.85);
    var cDirAng = screenAngle(-Math.sin(tC), -Math.cos(tC));
    draw.polyline(arcPts(cx, cy, arcR * 1.22, downAng, cDirAng))
      .fill('none').stroke({ color: '#555', width: 1 });
    var cMid = (downAng + cDirAng) / 2;
    txt(cx + (arcR * 1.22 + 12) * Math.cos(cMid), cy + (arcR * 1.22 + 12) * Math.sin(cMid) - 3,
      'θ_c', 14, '#333', 'middle', true);
  }

  // ---- incident ray (tail lower-left -> origin) ----
  var iTailX = plotX(-L * Math.sin(t1)), iTailY = plotY(-L * Math.cos(t1));
  ray(iTailX, iTailY, cx, cy, RAYCOL, 2.4, false, 1);
  var iDirAng = screenAngle(Math.sin(t1), Math.cos(t1));
  var iMidX = iTailX + (cx - iTailX) * 0.55, iMidY = iTailY + (cy - iTailY) * 0.55;
  arrowHead(iMidX, iMidY, iDirAng, ah, RAYCOL);
  var iTailAng = screenAngle(-Math.sin(t1), -Math.cos(t1));
  draw.polyline(arcPts(cx, cy, arcR, downAng, iTailAng)).fill('none').stroke({ color: '#333', width: 1 });
  var iMidA = (downAng + iTailAng) / 2;
  txt(cx + (arcR + 12) * Math.cos(iMidA), cy + (arcR + 12) * Math.sin(iMidA) - 3, 'θ₁', 14, '#111', 'middle', true);
  txt(iTailX - 8, iTailY - 6, 'Incident ray', 13, '#111', 'end', false);

  // ---- reflected ray (origin -> lower-right) ----
  var rEndX = plotX(L * Math.sin(t1)), rEndY = plotY(-L * Math.cos(t1));
  ray(cx, cy, rEndX, rEndY, RAYCOL, 2.4, false, 1);
  var rDirAng = screenAngle(Math.sin(t1), -Math.cos(t1));
  arrowHead(rEndX, rEndY, rDirAng, ah, RAYCOL);
  draw.polyline(arcPts(cx, cy, arcR, rDirAng, downAng)).fill('none').stroke({ color: '#333', width: 1 });
  var rMidA = (rDirAng + downAng) / 2;
  txt(cx + (arcR + 12) * Math.cos(rMidA), cy + (arcR + 12) * Math.sin(rMidA) - 3, 'θ₁', 14, '#111', 'middle', true);
  txt(rEndX + 6, rEndY + 4, 'Reflected ray', 13, '#111', 'start', false);

  // ---- refracted ray (origin -> upper-right into n2) ----
  if (refr) {
    var refrOp = Math.max(0, Math.min(1, (thetaC - theta1) / 2));
    var fEndX = plotX(L * Math.sin(t2)), fEndY = plotY(L * Math.cos(t2));
    ray(cx, cy, fEndX, fEndY, RAYCOL, 2.4, false, refrOp);
    var fDirAng = screenAngle(Math.sin(t2), Math.cos(t2));
    arrowHead(fEndX, fEndY, fDirAng, ah, RAYCOL).opacity(refrOp);
    draw.polyline(arcPts(cx, cy, arcR, upAng, fDirAng)).fill('none')
      .stroke({ color: '#333', width: 1 }).opacity(refrOp);
    var fMidA = (upAng + fDirAng) / 2;
    txt(cx + (arcR + 12) * Math.cos(fMidA), cy + (arcR + 12) * Math.sin(fMidA) - 3,
      'θ₂', 14, '#111', 'middle', true).opacity(refrOp);
    txt(fEndX + 4, fEndY - 8, 'Refracted ray', 13, '#111', 'start', false).opacity(refrOp);
  }

  // ---- tangent ray + right-angle marker exactly at critical ----
  if (atCrit) {
    ray(cx, cy, plotX(L), cy, RAYCOL, 2.4, false, 1);
    arrowHead(plotX(L), cy, 0, ah, RAYCOL);
    var s = Math.max(9, 0.032 * minDim);
    draw.polyline([
      (cx - s) + ',' + cy,
      (cx - s) + ',' + (cy - s),
      cx + ',' + (cy - s)
    ]).fill('none').stroke({ color: '#222', width: 1.4 });
    txt(cx + 8, cy - s - 6, 'θ₂ = 90°', 14, '#111', 'start', true);
  }

  // ---- total internal reflection label ----
  if (tir) {
    txt(plotX(1.35), plotY(-1.15), 'Total', 14, '#111', 'start', false);
    txt(plotX(1.35), plotY(-1.15) + 16, 'internal', 14, '#111', 'start', false);
    txt(plotX(1.35), plotY(-1.15) + 32, 'reflection', 14, '#111', 'start', false);
  }

  // hover info at incidence point
  draw.circle(20).center(cx, cy).fill('transparent').css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip('θ₁ = ' + theta1.toFixed(0) + '°,  θ_c = ' + thetaC.toFixed(1) + '°  →  ' +
        (tir ? 'total internal reflection' : (atCrit ? 'refracted ray tangent (θ₂ = 90°)' : 'θ₂ = ' + theta2.toFixed(1) + '°')), e);
    })
    .on('mouseleave', hideTooltip);
}

function update_incidentAngle(v) { theta1 = v; build(); }
function update_indexRatio(v) { ratio = v; build(); }
document.addEventListener('fig-resize', function () { build(); });

// ---- demo step player ----
var steps = [
  { t: 'Below the critical angle (panel a)', n: 'With θ₁ below θ_c the ray splits at the boundary: part reflects at θ₁ and part refracts into n₂, bending away from the normal at θ₂ because n₁ > n₂.', s: { incidentAngle: 30, indexRatio: 0.66 } },
  { t: 'At the critical angle (panel b)', n: 'Raising θ₁ to θ_c makes the refracted ray run exactly along the interface (θ₂ = 90°, marked by the right-angle square); this is the largest angle at which any light still escapes into n₂.', s: { incidentAngle: 41, indexRatio: 0.66 } },
  { t: 'Beyond the critical angle (panel c)', n: 'Pushing θ₁ past θ_c removes the refracted ray entirely — the dashed θ_c reference ray shows how far past it we are — and all light reflects back into n₁: total internal reflection.', s: { incidentAngle: 60, indexRatio: 0.66 } },
  { t: 'Shifting the threshold', n: 'Lowering n₂/n₁ slides the θ_c reference ray toward the normal, so the same incident angle that once transmitted now undergoes total internal reflection, illustrating sin(θ_c) = n₂/n₁.', s: { incidentAngle: 60, indexRatio: 0.4 } }
];
var curStep = 0;
function applyStep(i) {
  curStep = i;
  var st = steps[i].s;
  document.getElementById('incidentAngleInput').value = st.incidentAngle;
  document.getElementById('incidentAngleVal').value = st.incidentAngle;
  document.getElementById('indexRatioInput').value = st.indexRatio;
  document.getElementById('indexRatioVal').value = st.indexRatio;
  theta1 = st.incidentAngle; ratio = st.indexRatio;
  build();
  document.getElementById('demoNarration').textContent = steps[i].n;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep((curStep + 1) % steps.length); }
function prevStep() { applyStep((curStep - 1 + steps.length) % steps.length); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

